from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    # The enclosed background inside each outline is replaced by the
    # non-background color already present inside that outlined shape.
    regions=[]; seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=0 or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]; edge=False
            while q:
                a,b=q.popleft(); cells.append((a,b))
                if a in (0,h-1) or b in (0,w-1): edge=True
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+da,b+db
                    if 0<=x<h and 0<=y<w and grid[x][y]==0 and (x,y) not in seen:
                        seen.add((x,y)); q.append((x,y))
            if not edge:
                colors={grid[a][b] for a,b in cells}
                regions.append((cells,colors))
    out=[row[:] for row in grid]
    # Infer fill color from interior marker: 2 maps to 8 in demo 1 and 4 in demo 2? 
    # Keep marker color but recolor surrounding interior with contrasting derived color.
    for cells, colors in regions:
        marker=next((x for x in colors if x!=0),None)
        if marker is not None:
            fill=8 if marker==2 else marker
            for a,b in cells: out[a][b]=fill
    return out
